# Ticket numbers come from this sequence on PostgreSQL (apps.helpdesk.services.numbering): unique under concurrent
# creation, never below 1001. It is deliberately not owned by the column: Django resets every column-owned sequence
# to 1 (tests with reset_sequences), which would hand out low numbers again; reversing this migration drops it.
# Other databases (SQLite in local development) take the highest number plus one, so there is nothing to create.
TICKET_NUMBER_SEQUENCE = "CREATE SEQUENCE IF NOT EXISTS helpdesk_ticket_number_seq START WITH 1001 MINVALUE 1001"


def create_ticket_number_sequence(apps, schema_editor):
    if schema_editor.connection.vendor == "postgresql":
        schema_editor.execute(TICKET_NUMBER_SEQUENCE)


def drop_ticket_number_sequence(apps, schema_editor):
    if schema_editor.connection.vendor == "postgresql":
        schema_editor.execute("DROP SEQUENCE IF EXISTS helpdesk_ticket_number_seq")


